INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES ("vo_minigame_1004_top_1_000", 2, 1000101, 1, "vo_minigame_1004", 10001, "ふっふっふ、これでカヤぴぃとボスを見返してやるです！");
